// packages/core/test/review-tmp/enzymes-science-dedupe.test.ts (run with: npx vitest run test/review-tmp/enzymes-science-dedupe.test.ts)
import { describe, expect, it } from 'vitest';
import type { FragmentEnds } from '../../src/types';
import { getEnzyme } from '../../src/enzymes/enzyme';
import { digest, digestDetailed } from '../../src/enzymes/digest';

describe('identical breaks are merged before the sticky-end validity check', () => {
  it('EcoRI cut lost when an overlapping BsmBI site (same AATT break) runs into a sticky end', () => {
    // EcoRI GAATTC at [10,16): break (11,15). BsmBI reverse site GAGACG at [16,22): break (16+6-11, 16+6-7) = (11,15).
    // Right 5' overhang of 6: bases [18,24) are bottom-only, so the BsmBI site is not fully double-stranded.
    const seq = 'ACGTACGTAC' + 'GAATTC' + 'GAGACG' + 'TT';
    const ends: FragmentEnds = { left: { kind: 'blunt', length: 0 }, right: { kind: '5prime', length: 6 } };
    expect(digest(seq, 'linear', [getEnzyme('EcoRI')!], { ends })).toHaveLength(2); // passes
    const r = digestDetailed(seq, 'linear', [getEnzyme('BsmBI')!, getEnzyme('EcoRI')!], { ends });
    expect(r.fragments).toHaveLength(2); // FAILS: 1 fragment
  });

  it('single enzyme (MlyI): valid reverse site shadowed by a partly single-stranded forward site', () => {
    // MlyI GAGTC(5/5) blunt: forward site [0,5) -> cut 10; reverse site GACTC at [15,20) -> cut 15+5-10 = 10.
    const ends: FragmentEnds = { left: { kind: '5prime', length: 1 }, right: { kind: 'blunt', length: 0 } };
    const seq = 'GAGTC' + 'A'.repeat(10) + 'GACTC' + 'A'.repeat(10);
    expect(digest(seq, 'linear', [getEnzyme('MlyI')!])).toHaveLength(2); // passes (blunt ends)
    expect(digestDetailed(seq, 'linear', [getEnzyme('MlyI')!], { ends }).fragments).toHaveLength(2); // FAILS: 1
  });

  it('adding BsaI removes the cut that BsmAI makes alone', () => {
    // BsaI GGTCTC at [0,6) (base 0 single-stranded) and BsmAI GTCTC at [1,6) both make break (7,11).
    const ends: FragmentEnds = { left: { kind: '5prime', length: 1 }, right: { kind: 'blunt', length: 0 } };
    const seq = 'GGTCTC' + 'A'.repeat(24);
    expect(digest(seq, 'linear', [getEnzyme('BsmAI')!], { ends })).toHaveLength(2); // passes
    expect(digestDetailed(seq, 'linear', [getEnzyme('BsaI')!, getEnzyme('BsmAI')!], { ends }).fragments).toHaveLength(2); // FAILS: 1
  });
});

