import { expect, it } from 'vitest';
import type { FragmentEnds } from '../../src/types';
import { getEnzyme } from '../../src/enzymes/enzyme';
import type { RestrictionEnzyme } from '../../src/enzymes/enzyme';
import { digest } from '../../src/enzymes/digest';
const E = (n: string) => getEnzyme(n) as RestrictionEnzyme;

it('BsaI + BsmAI: adding BsaI removes the BsmAI cut (pydna cuts)', () => {
  // BsaI GGTCTC(1/5) at 0 and BsmAI GTCTC(1/5) at 1 make the same break (top 7, bottom 11).
  // Left 1-nt 5' overhang: BsaI's site is partly single-stranded, BsmAI's is fully double-stranded.
  const seq = 'GGTCTC' + 'A'.repeat(24);
  const ends: FragmentEnds = { left: { kind: '5prime', length: 1 }, right: { kind: 'blunt', length: 0 } };
  expect(digest(seq, 'linear', [E('BsmAI')], { ends })).toHaveLength(2); // passes
  expect(digest(seq, 'linear', [E('BsaI'), E('BsmAI')], { ends })).toHaveLength(2); // FAILS: got 1
});

it('MlyI twin sites: the fully double-stranded site loses its cut', () => {
  // MlyI GAGTC(5/5): forward site at 1 (straddles a 2-nt 5' overhang) and reverse site GACTC at 16
  // both make the blunt break at 11; findSites lists both with cuts [{top:11,bottom:11}]
  const seq = 'A' + 'GAGTC' + 'A'.repeat(10) + 'GACTC' + 'A'.repeat(9);
  const ends: FragmentEnds = { left: { kind: '5prime', length: 2 }, right: { kind: 'blunt', length: 0 } };
  expect(digest(seq, 'linear', [E('MlyI')], { ends })).toHaveLength(2); // FAILS: got 1
});

