it('pUC19 + AccII + BsmBI: different number of fragments', () => {
  expect(digestSizes(rc, 'circular', [E('AccII'), E('BsmBI')])).toHaveLength(digestSizes(puc19, 'circular', [E('AccII'), E('BsmBI')]).length);
  // FAILS: expected [581,545,493,332,330,198,100,63,44,2,2] to have a length of 10 but got 11
});

