// packages/core/test/review-tmp/enzymes-robustness-repro.test.ts
import { expect, it } from 'vitest';
import { getEnzyme } from '../../src/enzymes/enzyme';
import { countCuts, findSites } from '../../src/enzymes/search';
import { digest, digestDetailed } from '../../src/enzymes/digest';
import { uniqueCutters } from '../../src/enzymes/sets';
const E = (n: string) => getEnzyme(n)!;

it('map of a sticky-ended EcoRI-XhoI insert agrees with what the digest can cut', () => {
  const insert = 'ATGAGTAAAGGAGAAGAACTTTTCACTGGAGTTGTCCCAATTCTTGTTGAATTAGATGGTGATGTTAATGGGCACAAATTTTCTGTC';
  expect(insert.includes('TCGA')).toBe(false); // no internal TaqI site
  const vector = 'GGGGG' + 'GAATTC' + insert + 'CTCGAG' + 'GGGGG';
  const [, frag] = digest(vector, 'linear', [E('EcoRI'), E('XhoI')]); // directional-cloning insert
  expect(frag.ends).toEqual({ left: { kind: '5prime', length: 4 }, right: { kind: '5prime', length: 4 } });
  const sites = findSites(frag.seq, 'linear', [E('TaqI'), E('EcoRI'), E('XhoI')]);
  const report = digestDetailed(frag.seq, 'linear', [E('TaqI')], { ends: frag.ends });
  expect(report.fragments).toHaveLength(1); // passes: TaqI cannot cut
  expect(report.skipped.map((s) => s.reason)).toEqual(['end']); // passes
  expect(countCuts(sites).get('TaqI') ?? 0).toBe(report.fragments.length - 1); // FAILS: expected 0, received 1
  expect(uniqueCutters(sites)).not.toContain('TaqI'); // also fails: ['TaqI']
});
