import { expect, it } from 'vitest';
import { getEnzyme } from '../../src/enzymes/enzyme';
import { digest } from '../../src/enzymes/digest';
const E = (n: string) => getEnzyme(n)!;

it('digest results are fresh, unshared, mutable objects', () => {
  const [uncut] = digest('ACGTACGT', 'circular', [E('EcoRI')]);
  expect(uncut.ends.left).not.toBe(uncut.ends.right); // FAILS: same frozen BLUNT object
  // uncut.ends.left.length = 0  -> TypeError: Cannot assign to read only property 'length' of object '#<Object>'
  const frags = digest('AAGAATTCAAGAATTCAA', 'linear', [E('EcoRI')]);
  // frags[0].rightCut === frags[1].leftCut is true; after `frags[1].leftCut!.top -= 3`,
  // frags[0].rightCut becomes { enzyme: 'EcoRI', top: 0, bottom: 7 }
  expect(frags[0].rightCut).not.toBe(frags[1].leftCut);
});

